with order_items_by_product as (select product_id, sum(unit_price * quantity) as revenue, count(*) as total_count from order_items group by product_id) select products.id, products.supplier_id, products.stock_qty, order_items_by_product.revenue, order_items_by_product.total_count from products inner join order_items_by_product on products.id = order_items_by_product.product_id order by 2
